// checkout service, without a sidecar
const cert = loadClientCert();
const conn = tls.connect({ cert, host: 'payments.internal' });
let attempt = 0;
while (attempt < 3) {
  try {
    return await callPayments(conn, order);
  } catch (err) {
    attempt++;
  }
}
throw new Error('payments call failed after retries');

